const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var boston = ee.Geometry.Point(-71.0589, 42.3601);
  var startDate = '2019-01-29';
  var endDate = '2019-02-06'; // Exclusive end date

  // 2. Data Acquisition - ERA5 Daily for air temperature at 2m
  var tempCollection = ee.ImageCollection('ECMWF/ERA5/DAILY')
    .filterBounds(boston)
    .filterDate(startDate, endDate)
    .select('mean_2m_air_temperature');

  var collectionSize = tempCollection.size().getInfo();
  print(`ERA5 Images: ${collectionSize}`);

  if (collectionSize === 0) {
    print("No temperature data found for the date range");
    print("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get daily max temperatures
  var tempStats = tempCollection.map(function(image) {
    var date = image.date().format('YYYY-MM-dd');
    var tempK = image.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: boston,
      scale: 1000
    }).get('mean_2m_air_temperature');

    // Convert Kelvin to Celsius
    var tempC = ee.Number(tempK).subtract(273.15);

    return ee.Feature(null, {
      'date': date,
      'tempC': tempC
    });
  });

  var tempList = tempStats.reduceColumns({
    reducer: ee.Reducer.toList(2),
    selectors: ['date', 'tempC']
  }).get('list').getInfo();

  // 4. Calculation - Find temperature range
  var temps = tempList.map(item => item[1]);
  var dates = tempList.map(item => item[0]);

  print("Daily Temperatures:");
  for (var i = 0; i < dates.length; i++) {
    print(`${dates[i]}: ${temps[i].toFixed(1)}°C`);
  }

  var maxTemp = Math.max(...temps);
  var minTemp = Math.min(...temps);
  var tempRange = maxTemp - minTemp;

  print(`Max Temp: ${maxTemp.toFixed(1)}°C, Min Temp: ${minTemp.toFixed(1)}°C`);
  print(`Temperature Range: ${tempRange.toFixed(1)}°C`);

  // 5. Validation & Final Answer
  if (tempRange === null || isNaN(tempRange) || tempRange > 100 || tempRange < -100) {
    print("<answer>C3</answer>");
  } else if (tempRange >= 22) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
